/*
 * migration_183 —— 補回 56 筆流水的對方帳號
 * ============================================================
 * 2026-08-31 使用者：「沒讀到帳號」「好多筆 都是有銀行 沒帳戶」
 *
 * 【為什麼會少】
 *
 * 舊版 `groupRows` 用 `Math.round(top / 3)` 分行 —— **絕對位置**切格子。
 * 帳號那一行離格子邊界只有 0.13pt，而 pdfplumber（字框頂）與
 * pdfjs（baseline）的 top 差不到 1pt —— 就足以把帳號推進**前一格**。
 * 前一格沒有序號，`pickTxn` 直接回 null → 那一行連同帳號消失，**不報錯**。
 *
 * 抓得到的只是離邊界遠一點（0.33 以上），所以症狀是
 * 「同一頁、同一欄、格式一樣，抓到兩筆漏兩筆」。
 *
 * 程式已改成**依間距分行**（同一支 commit），之後匯入的不會再漏。
 * 這一支負責**已經匯進來的**。
 *
 * ============================================================
 * 【★★★ 為什麼不能重匯】
 *
 * 使用者：「我重新上傳會洗掉 之前的編輯摘要耶」。
 * 撤銷是整批刪流水，人工編輯過的 `memo` 會一起消失。
 *
 * 所以這一支**只寫 `ref_no`，而且只寫目前是空的那些**：
 *   · 不碰 `memo`（那是人可以編輯的唯一欄位）
 *   · 不碰金額、日期、餘額
 *   · 已經有帳號的一列都不動
 *
 * ============================================================
 * 【資料哪來的】
 *
 * 12 份對帳單 PDF 用 pdfplumber 抽詞、跑**修好後的**同一支 `parseStatement`，
 * 得到 1,220 筆帶帳號的流水。對應鑰匙跟匯入時的去重鑰匙一致：
 *
 *     末五碼 ＋ 帳務日 ＋ **銀行印的**餘額 ＋ 交易時間
 *
 * ★ 用 `bank_balance` 不用 `balance` —— balance 是我們自己算的，
 *   會跟著「這份對帳單從哪裡起算」跑（migration_143）。
 *
 * ★ 交易時間 null 收斂成 00:00:00，跟 `txnKey()` 一致。
 *
 * ★★ 期間重疊時同一筆會在兩份 PDF 出現。產生資料時已經比對過：
 *   同一鑰匙若解析出**兩種帳號**就整筆跳過，不猜。（實際發生 0 次）
 */

create temp table _fix183 (
  tail text, post_date date, bank_balance numeric, txn_time time, ref_no text
) on commit drop;

;

-- ══════════════════════════════════════════════════════════
-- 預覽：這一支會動到哪幾列。**先看這張，確認了再往下跑 UPDATE。**
-- ══════════════════════════════════════════════════════════
select a.name as "帳戶", t.post_date as "帳務日", t.description as "型態",
       t.counterparty as "對方", f.ref_no as "要補上的帳號", t.memo as "摘要（不會動）"
  from public.bank_transactions t
  join public.bank_accounts a on a.id = t.account_id
  join _fix183 f
    on f.tail = a.account_no_tail
   and f.post_date = t.post_date
   and f.bank_balance = t.bank_balance
   and f.txn_time = coalesce(t.txn_time, '00:00:00'::time)
 where coalesce(t.ref_no, '') = ''
 order by t.post_date desc;


-- ══════════════════════════════════════════════════════════
-- 實際補上。★ 只寫 ref_no，只寫目前是空的那些。
-- ══════════════════════════════════════════════════════════
update public.bank_transactions t
   set ref_no = f.ref_no
  from _fix183 f, public.bank_accounts a
 where a.id = t.account_id
   and f.tail = a.account_no_tail
   and f.post_date = t.post_date
   and f.bank_balance = t.bank_balance
   and f.txn_time = coalesce(t.txn_time, '00:00:00'::time)
   and coalesce(t.ref_no, '') = '';


-- ── 記錄執行 ───────────────────────────────────────
do $$ begin
  if to_regprocedure('public.record_migration(text)') is not null then
    perform public.record_migration('183_backfill_ref_no');
  end if;
end $$;


-- ══════════════════════════════════════════════════════════
-- 自檢
-- ══════════════════════════════════════════════════════════
select v."檢查項目", v."結果", v."說明" from (

  select 1, '★★★ 還有幾筆「對方是銀行但沒帳號」',
         (select count(*)::text || ' 筆'
            from public.bank_transactions t
           where coalesce(t.ref_no,'') = ''
             and coalesce(t.counterparty,'') <> ''),
         '跑之前是 56 筆。剩下的多半是這 12 份 PDF 沒涵蓋的期間'

  union all
  select 2, '★★ 摘要一個字都沒動',
         (select count(*)::text || ' 筆有摘要 ／ 共 '
                 || (select count(*) from public.bank_transactions)::text || ' 筆'
            from public.bank_transactions where coalesce(memo,'') <> ''),
         '這支只寫 ref_no。這兩個數字跟跑之前要一模一樣'

  union all
  select 3, '★★ 金額與餘額沒動',
         (select 'Σ支出 ' || to_char(coalesce(sum(debit),0), 'FM999,999,999')
                 || ' ／ Σ存入 ' || to_char(coalesce(sum(credit),0), 'FM999,999,999')
            from public.bank_transactions),
         '這支不碰任何金額。對不上就是 where 條件寫錯了'

  union all
  select 4, '現在有帳號的比例',
         (select count(*) filter (where coalesce(ref_no,'') <> '')::text || ' ／ '
                 || count(*)::text || ' 筆'
            from public.bank_transactions),
         '不會到 100% —— 有些交易本來就沒有對方帳號（利息、手續費…）'

) v(ord, "檢查項目", "結果", "說明") order by v.ord;
